bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i "$cid" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
const pub=readFileSync('/opt/videobot/src/telegram/paidListingPublisher.mjs','utf8');
const pd=readFileSync('/opt/videobot/src/telegram/paidMedia.mjs','utf8');
const flags={paidMethod:pub.includes("telegramApi('sendPaidMedia',paid)"),nativePaidCheck:pub.includes("nativePaid.star_count !== listing.priceStars"),paidVideoType:pd.includes("type:'video'"),starCount:pd.includes("star_count:priceStars"),freePublicVideo:pub.includes("telegramApi('sendVideo'")};
console.log(JSON.stringify({running:true,flags}));
if(Object.values(flags).slice(0,4).includes(false)||flags.freePublicVideo)process.exit(72);
JS
docker inspect "$cid" --format 'ACTIVE_IMAGE={{.Config.Image}} STATUS={{.State.Status}}'
